  <style id="ticc-nav-fix" dangerouslySetInnerHTML={{__html: `
/* 원본 Wix 메뉴/헤더 숨김 + 아래 독립 드롭다운 바로 대체 */
#pinnedTopRight{display:none !important;}
#SITE_HEADER{display:none !important;}

.ticc-mnav{position:sticky;top:0;z-index:9999;width:100%;box-sizing:border-box;
  background:#dbb89a;display:flex;flex-wrap:wrap;align-items:center;gap:0 4px;padding:0 14px;
  font-family:avenir-lt-w01_85-heavy1475544,'Noto Sans KR',sans-serif;}
.ticc-mnav .ticc-brand{margin-right:auto;font-size:19px;font-weight:700;
  text-decoration:underline;text-underline-offset:4px;padding:0 12px 0 0;color:#fff;white-space:nowrap;}
.ticc-mnav .ticc-brand:hover{opacity:.85;}
.ticc-mnav .ticc-brand-break{display:none;}

.ticc-mnav ul.tmn{display:flex;flex-wrap:wrap;align-items:center;list-style:none;margin:0;padding:0;gap:0 2px;}
.ticc-mnav .tmn-i{position:relative;}
.ticc-mnav .tmn-top{display:flex;align-items:center;height:52px;padding:0 14px;
  color:#3a2f28;font-size:14px;font-weight:600;white-space:nowrap;cursor:pointer;text-decoration:none;
  background:transparent;border:none;font-family:inherit;transition:color .2s,background .2s;}
.ticc-mnav .tmn-i:hover>.tmn-top,.ticc-mnav .tmn-i:focus-within>.tmn-top{color:#8a1a1a;background:rgba(255,255,255,0.18);}

.ticc-mnav .tmn-sub{position:absolute;top:100%;left:0;min-width:200px;background:#fff;
  box-shadow:0 8px 24px rgba(0,0,0,0.18);border-radius:0 0 10px 10px;list-style:none;margin:0;padding:6px 0;
  display:none;z-index:10000;}
.ticc-mnav .tmn-i:hover>.tmn-sub,.ticc-mnav .tmn-i:focus-within>.tmn-sub{display:block;}
.ticc-mnav .tmn-sub li{margin:0;}
.ticc-mnav .tmn-sub a{display:block;padding:10px 18px;color:#2b2b2b;font-size:13.5px;text-decoration:none;white-space:nowrap;}
.ticc-mnav .tmn-sub a:hover{background:#f2ece4;color:#8a1a1a;}

@media (max-width:640px){
  .ticc-mnav{padding:0 8px;}
  .ticc-mnav .ticc-brand{flex-basis:100%;height:auto;padding:8px 0 6px;font-size:15px;white-space:normal;line-height:1.3;text-align:center;}
  .ticc-mnav .ticc-brand-break{display:inline;}
  .ticc-mnav ul.tmn{width:100%;justify-content:center;flex-wrap:wrap;}
  .ticc-mnav .tmn-i{width:auto;}
  .ticc-mnav .tmn-top{height:42px;padding:0 8px;font-size:13px;}
}
` }} />
